                param.put(JR_PARAMETER_LOGO_COMUNE, logoComune);
            }

            param.put(JR_PARAMETER_COMUNE, organization.getName());
            param.put(JR_PARAMETER_NOME_BANDO, bando.getNome());

            // URL del portale per caricare risorse dalla Document Library
            try {
                Company company = companyLocalService.getCompany(organization.getCompanyId());
                String portalURL = company.getPortalURL(groupId);
                param.put(JR_PARAMETER_URL_PORTALE, portalURL);
            } catch (Exception e) {
                log.warn("Impossibile ottenere URL portale: " + e.getMessage());
            }

            // Nome e cognome dell'utente che genera il documento
            if (Validator.isNotNull(codiceFiscaleRichiedente)) {
                User user = userLocalService.fetchUserByScreenName(organization.getCompanyId(), codiceFiscaleRichiedente);
                if (user != null) {
                    String nomeCognome = user.getFirstName() + " " + user.getLastName();
                    param.put(JR_PARAMETER_NOME_COGNOME_UTENTE, nomeCognome);
                }
            }

            SimpleDateFormat dateFormat = new SimpleDateFormat("dd/MM/yyyy");
            SimpleDateFormat dateTimeFormat = new SimpleDateFormat("dd/MM/yyyy HH:mm");
            Date currentDate = new Date();

            IstanzaDomandaBando istanzaDomandaBando = null;
            if (istanzaDomandaBandoId > 0) {
                istanzaDomandaBando = istanzaDomandaBandoLocalService.fetchIstanzaDomandaBando(istanzaDomandaBandoId);
            }

            long commentoDomandaBandoId = 0L;
            if (istanzaDomandaBando != null) {
                commentoDomandaBandoId = istanzaDomandaBando.getCommentoDomandaBandoId();
            }

            AnnotazioneOperatore notaOperatore = getCommentoText(commentoDomandaBandoId);

            param.put("denominazioneBando", bando.getNome());
            param.put("idPratica", String.valueOf(domandaBando.getDomandaBandoId()));
            param.put("dataArrivo", domandaBando.getCreateDate() != null ? dateFormat.format(domandaBando.getCreateDate()) : "");
            param.put("numeroProtocollo", domandaBando.getNumeroProtocollo() != null ? domandaBando.getNumeroProtocollo() : "N/A");
            param.put("oggettoNotaOperatore", notaOperatore.getOggetto());
            param.put("notaOperatore", notaOperatore.getTesto());
            param.put("dataOraRichiesta", dateTimeFormat.format(currentDate));

            // Note: testoAntipazione, numeroProtocolloAntipazione, dataProtocolloAntipazione
            // are handled in generaPDFRichiestaSoccorsoIstruttoria method via anticipazioneInfo map
            param.put("testoAntipazione", "");
            param.put("numeroProtocolloAntipazione", "");
            param.put("dataProtocolloAntipazione", "");

            String nomeCognomeOperatore = "";
            String titoloRuoloOperatore = "";

            if (istanzaDomandaBando != null && istanzaDomandaBando.getUserId() > 0) {
                nomeCognomeOperatore = getOperatorName(istanzaDomandaBando.getUserId());
                titoloRuoloOperatore = getOperatorRoleTitle(istanzaDomandaBando.getUserId(), organizationId);
            }

            param.put("nomeCognomeOperatore", nomeCognomeOperatore);
            param.put("titoloRuoloOperatore", titoloRuoloOperatore);
            param.put("mostraFirma", titoloRuoloOperatore != null && !titoloRuoloOperatore.isEmpty());

            // Costruisce lista allegati DTO dagli allegati caricati per questa istanza di integrazione
            List<AllegatoReportDTO> listaAllegati = new ArrayList<>();

            List<AllegatoDomandaBando> allegatiDomanda = new ArrayList<AllegatoDomandaBando>();
            if (istanzaDomandaBandoId > 0) {
                // Per le integrazioni, recupera solo gli allegati di questa specifica istanza
                allegatiDomanda = allegatoDomandaBandoLocalService
                        .getListaAllegatiByIstanzaDomandaBandoIdAndInterno(istanzaDomandaBandoId, false);
            }

            for (AllegatoDomandaBando allegato : allegatiDomanda) {
                // Recupera denominazione dalla DefinizioneAllegato o usa descrizione/titolo
                String denominazione = "";
                if (allegato.getDefinizioneAllegatoId() > 0) {
                    DefinizioneAllegato defAllegato = definizioneAllegatoLocalService.fetchDefinizioneAllegato(allegato.getDefinizioneAllegatoId());
                    if (defAllegato != null) {
                        denominazione = defAllegato.getDenominazione() != null ? defAllegato.getDenominazione() : "";
                    }
                }
                if (Validator.isNull(denominazione)) {
                    denominazione = allegato.getDescrizione() != null ? allegato.getDescrizione() :
                            (allegato.getTitolo() != null ? allegato.getTitolo() : "Allegato");
                }

                String nomeFile = allegato.getNome() != null ? allegato.getNome() : "";
                String impronta;
                boolean firmato;

                if (EsitoVerificaFirma.ERRORE.name().equals(allegato.getEsitoVerificaFirma())) {
                    impronta = "Non disponibile";
                    firmato = false;
                } else {
                    impronta = allegato.getImpronta() != null ? allegato.getImpronta() : "";
                    firmato = allegato.isFirmatoDigitalmente();
                }

                String firmatario = allegato.getFirmatario() != null ? allegato.getFirmatario() : "";
                listaAllegati.add(new AllegatoReportDTO(denominazione, nomeFile, impronta, firmato, firmatario));
            }

            param.put(JR_PARAMETER_LISTA_ALLEGATI, new JRBeanCollectionDataSource(listaAllegati));

            JasperPrint jasperPrint = JasperFillManager.fillReport(reportPrincipaleJasperReport, param, jsonDataSource);

            ByteArrayOutputStream out = new ByteArrayOutputStream();
            JasperExportManager.exportReportToPdfStream(jasperPrint, out);
            return out.toByteArray();
        }
        catch (Exception e) {
            log.error("generaPDFIntegrazioni :: " + e.getMessage(), e);
            throw new PDFServiceException("Errore durante il processo di generazione del PDF integrazioni :: " + e.getMessage(), e);
        }
    }

    /**
     * Configura SSL per accettare tutti i certificati.
     * Necessario quando il server deve fare richieste HTTPS a se stesso.
     */
    private void configureTrustAllCertificates() {
        try {
            TrustManager[] trustAllCerts = new TrustManager[] {
                    new X509TrustManager() {
                        public X509Certificate[] getAcceptedIssuers() { return null; }
                        public void checkClientTrusted(X509Certificate[] certs, String authType) { }
                        public void checkServerTrusted(X509Certificate[] certs, String authType) { }
                    }
            };

            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, trustAllCerts, new java.security.SecureRandom());
            HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory());

            HostnameVerifier allHostsValid = (hostname, session) -> true;
            HttpsURLConnection.setDefaultHostnameVerifier(allHostsValid);

            log.debug("SSL TrustAll configurato correttamente");
        } catch (Exception e) {
            log.warn("Impossibile configurare SSL TrustAll: " + e.getMessage());
        }
    }

