    private static void configureTrustAllCertificates() {
        try {
            TrustManager[] trustAllCerts = new TrustManager[] {
                    new X509TrustManager() {
                        @Override
                        public X509Certificate[] getAcceptedIssuers() {
                            return new X509Certificate[0];
                        }

                        @Override
                        public void checkClientTrusted(X509Certificate[] certs, String authType) {
                            // nessuna verifica: necessario solo per caricare il logo remoto in test
                        }

                        @Override
                        public void checkServerTrusted(X509Certificate[] certs, String authType) {
                            // nessuna verifica: necessario solo per caricare il logo remoto in test
                        }
                    }
            };

            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, trustAllCerts, new java.security.SecureRandom());
            HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory());

            HostnameVerifier allHostsValid = (hostname, session) -> true;
            HttpsURLConnection.setDefaultHostnameVerifier(allHostsValid);
        } catch (Exception e) {
            // in assenza di rete il logo remoto non verrà caricato, ma il resto del PDF sì
        }
    }

    /**
     * Bean usato dal subreport allegati: i nomi delle proprietà devono
     * corrispondere ai field dichiarati in {@code allegati_subreport_istanza.jrxml}.
     */
    public static class AllegatoBean {

        private final String denominazione;
        private final String nomeFile;
        private final String impronta;
        private final boolean firmato;
        private final String firmatario;

        public AllegatoBean(String denominazione, String nomeFile, String impronta, boolean firmato, String firmatario) {
            this.denominazione = denominazione;
            this.nomeFile = nomeFile;
            this.impronta = impronta;
            this.firmato = firmato;
            this.firmatario = firmatario;
        }

        public String getDenominazione() {
            return denominazione;
        }

        public String getNomeFile() {
            return nomeFile;
        }

        public String getImpronta() {
            return impronta;
        }

        public boolean getFirmato() {
            return firmato;
        }

        public String getFirmatario() {
            return firmatario;
        }
    }
}

